export type TranslationSchema = typeof translationSchema;
export type Locale = "en" | "es" | "pt" | "fr" | "de" | "ja" | "ko" | "zh" | "hi" | "ru" | "tr" | "ar" | "id" | "it" | "nl" | "pl" | "vi";
export type Namespace = "aboutLegal" | "accessibility" | "achievements" | "ads" | "alerts" | "auth" | "coinPurchase" | "common" | "credits" | "devtools" | "errors" | "game" | "leaderboard" | "levelUpFanfare" | "logs" | "loss" | "navigation" | "onboarding" | "profile" | "settings" | "shop" | "stats" | "streakFanfare" | "test" | "tooltips" | "victory";

export type DeepLeafKeys<T, Prefix extends string = ""> = T extends string
  ? Prefix
  : {
      [K in keyof T & string]: DeepLeafKeys<T[K], Prefix extends "" ? K : `${Prefix}.${K}`>;
    }[keyof T & string];

export type TranslationKey = DeepLeafKeys<TranslationSchema>;

export type LanguageOption = {
  code: Locale;
  label: string;
};
